const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tx=(x,y,s,n=17)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="#f8f4ed" font-family="sans-serif" font-size="${n}">${esc(s)}</text>`;
const path=(d,c='#b7cac5',w=3)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/>`;
const cell=(x,y,label,colour='#b6ccbe',nucleus=true)=>`<circle cx="${x}" cy="${y}" r="37" fill="#355769" stroke="${colour}" stroke-width="3"/>${nucleus?`<circle cx="${x}" cy="${y}" r="13" fill="${colour}"/>`:''}${tx(x,y+63,label,15)}`;
const box=(x,y,w,h,c)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="14" fill="${c}" stroke="#a6beb8"/>`;
export const histSVG=(a,label)=>`<svg viewBox="0 0 560 420" role="img" aria-label="${esc(label)}">${a}</svg>`;
export function cloneFigure({kind='adult-clone',progress=0}={}){let p=Math.max(0,Math.min(1,progress)),stage=Math.min(3,Math.floor(p*4)),a='';if(kind==='adult-clone'){a=tx(280,30,'Follow the adult nuclear information',22)+cell(100,115,'Body cell A','#eeb291',false)+cell(350,115,'Egg B, nucleus removed','#b9cfca',false)+path('M150 115H290');let x=stage===0?100:stage===1?100+(p*4-1)*250:350;a+=`<circle cx="${x}" cy="115" r="13" fill="#eeb291"/>`;if(stage>=2)a+=cell(175,280,'Embryo','#eeb291')+cell(225,280,'','#eeb291');if(stage===3)a+=box(345,238,145,85,'#554a5b')+tx(417,288,'Host uterus C',15);a+=tx(280,385,['Remove egg nucleus','Insert adult body-cell nucleus','Stimulate division → embryo','Transfer embryo to host uterus'][stage],18);}else if(kind==='embryo'){a=tx(280,30,'Split before cells specialise',22);for(let i=0;i<4;i++)a+=cell(100+i%2*30+(stage>0?i%2*200:0),150+Math.floor(i/2)*30,'','#edb191');if(stage>=2){a+=box(55,270,180,65,'#554a5b')+box(315,270,180,65,'#554a5b')+tx(145,308,'Host mother 1',16)+tx(405,308,'Host mother 2',16);}a+=tx(280,385,['Early unspecialised embryo','Separate cell groups','Transfer separate embryos','Embryos develop in hosts'][stage],18);}else{a=tx(280,30,'Tissue culture: multiply plant cells',22)+path('M100 220V95M100 140Q40 100 65 75M100 175Q165 100 165 135','#a9c8b4',6);if(stage>=1)a+=cell(265,145,'Small cell group','#a8c7b4');if(stage>=2)for(let i=0;i<3;i++)a+=cell(395+i%2*60,130+Math.floor(i/2)*75,'','#a8c7b4');if(stage===3)for(let x of[170,280,390])a+=path(`M${x} 310v-65m0 25q-30 -40 -35 -10m35 0q30 -40 35 -10`,'#a9c8b4',5);a+=tx(280,385,['Select useful or rare parent','Take a small cell sample','Grow cells in culture','Develop cloned plants'][stage],18);}a+=tx(280,412,'Conceptual sequence · timing and scale symbolic · not a protocol',12);return histSVG(a,kind+' conceptual stage '+(stage+1)+'. Adult-cloning nuclear genome follows donor A, not egg donor B or host C. Plant and embryo methods differ.');}
export function speciationFigure({progress=0}={}){let p=Math.max(0,Math.min(1,progress)),stage=Math.min(3,Math.floor(p*4)),a=tx(280,30,'Inherited divergence over generations',22)+box(30,90,500,220,'#304b43');if(stage>=1)a+=path('M280 90v220','#8ebdc8',20);for(let i=0;i<12;i++){let x=70+(i%6)*80,y=150+Math.floor(i/6)*90,colour=stage>=2?(x<280?'#dfba89':'#c5b2cf'):(i%2?'#dfba89':'#c5b2cf');a+=`<circle cx="${x}" cy="${y}" r="17" fill="${colour}"/>`+tx(x,y+38,stage>=2?(x<280?'A':'B'):(i%2?'A':'B'),13);}a+=tx(280,350,['One population with inherited variation','Barrier reduces gene flow','Different selection → inherited divergence','Cannot interbreed to produce fertile offspring'][stage],17)+tx(280,389,'Colours summarise cohorts, not individuals changing by need',13)+tx(280,411,'Conditional pathway · many generations compressed · no guarantee',12);return histSVG(a,'Speciation stage '+(stage+1)+'. Barrier reduces gene flow; inherited population differences may accumulate until reproductive isolation. Dots summarise successive cohorts, not recoloured individuals.');}
export function fossilFigure({progress=0}={}){let p=Math.max(0,Math.min(1,progress)),stage=Math.min(3,Math.floor(p*4)),a=tx(280,30,'One fossil pathway: mineral replacement',22);for(let i=0;i<3;i++)a+=`<rect x="35" y="${170+i*65}" width="490" height="65" fill="${['#52676a','#716556','#8c765b'][i]}"/>`;let y=stage?260:120;a+=`<ellipse cx="280" cy="${y}" rx="65" ry="32" fill="${stage>=2?'#d7be91':'#c1cfc6'}" stroke="#f0e2ca" stroke-width="3"/>`;for(let i=-2;i<=2;i++)a+=path(`M${280+i*18} ${y-25}q18 25 0 50`,stage>=2?'#716047':'#64777a',2);if(stage>=2)for(let i=0;i<12;i++){let x=210+i*12;a+=`<circle cx="${x}" cy="${stage===2?170+(p*4-2)*60:230}" r="3" fill="#edc392"/>`;}a+=tx(280,80,['Remains enter sediment','Burial and decay begin','Minerals replace material','Rock preserves evidence of past life'][stage],18)+tx(280,392,'Other pathways: prevented decay or preserved traces',15)+tx(280,413,'Symbolic burial, chemistry and timescale · not every organism fossilises',12);return histSVG(a,'Mineral-replacement fossil pathway stage '+(stage+1)+'. Preserved remains and traces are alternative pathways. Not real geological rates.');}
export function rockFigure(){let a=tx(280,30,'Original rock and branching evidence',22);for(let[i,v]of[['C · top · feature 4','#536b70'],['B · middle · feature 4','#74695b'],['A · bottom · feature 2','#8b745a']].entries())a+=box(25,80+i*65,270,57,v[1])+tx(160,115+i*65,v[0],16);a+=path('M340 290V120h170M340 200h90v-45h80M430 200v70h80')+tx(340,320,'R',15)+tx(433,220,'S',15)+tx(525,125,'X',16)+tx(525,160,'Y',16)+tx(525,275,'Z',16)+tx(280,365,'Undisturbed layers: lower is older, not an exact date',15)+tx(280,403,'Y/Z share S; X/Y share older R · modern tips are not parents',14);return histSVG(a,'Original supplied undisturbed strata: bottom A feature2, middle B4, top C4. Tree R branches to X and S; S branches to Y and Z. Relative rock order and branching relationships, not numerical dates.');}
const evidence={
'clone-methods':['Tissue culture: small plant-cell groups','Cuttings: pieces of the parent plant','Embryo splitting: early unspecialised cells'],
'clone-evidence':['Nuclear genome follows body-cell donor A','Useful copies ≠ guaranteed phenotype or success','Weigh diversity, welfare and ethical concerns'],
darwin:['Voyage observations + experiments + discussions','Geology and fossils added evidence','1859: On the Origin of Species'],
mechanisms:['Acquired change → inherited? Lamarck-style claim','Inherited variation → reproductive success: selection','Most acquired lifetime changes are not inherited'],
acceptance:['Prevailing beliefs challenged','Initial evidence did not convince many scientists','Inheritance mechanism not yet understood'],
wallace:['Independent natural selection; worldwide evidence','1858: joint writings with Darwin','Warning colouration and speciation research'],
'species-evidence':['Barrier ≠ instant new species','Appearance alone is insufficient','Test ability to produce fertile offspring'],
mendel:['Plant crosses → inherited units','Later evidence explained wider significance','Modern gene theory: many scientists'],
'pea-data':['Fictional pea sample: 72 dominant, 24 recessive','Total: 96 plants · use the whole sample','Observed proportions are not exact family promises'],
'genetics-timeline':['Mid-19th: Mendel → late-19th: chromosomes','Early-20th: genes linked to chromosomes','Mid-20th: DNA structure and gene function'],
'evolution-evidence':['Genes explain inherited characteristics','Fossils document past organisms','Bacterial resistance shows population change'],
'fossil-methods':['Absent decay conditions → preserved material','Mineral replacement during decay','Footprints and burrows → trace fossils'],
'fossil-limits':['Soft bodies often leave few traces','Geological activity destroys some evidence','Gaps limit certainty; they do not prove absence']};
export function histFigure(o={}){if(o.concealed)return histSVG(tx(280,210,'Predict, then reveal the evidence',22),'Evidence concealed until prediction');if(['adult-clone','plant-clone','embryo'].includes(o.kind))return cloneFigure(o);if(o.kind==='speciation')return speciationFigure(o);if(o.kind==='fossil-process')return fossilFigure(o);if(o.kind==='rock-data')return rockFigure();let rows=evidence[o.kind]||evidence.darwin;return histSVG(tx(280,35,'Follow the evidence',23)+rows.map((s,i)=>tx(280,125+i*88,s,17)).join('')+tx(280,410,'Original educational comparison · interpret the supplied context',13),'Evidence comparison. '+rows.join('. '));}
